    #include <bits/stdc++.h>
using namespace std;

// Structure of Node
struct Node {
    int data;
    Node* next;

    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Function to check if value exists in result list
bool isPresent(Node* head, int value) {
    while (head) {
        if (head->data == value)
            return true;
        head = head->next;
    }
    return false;
}

// Naive union 
Node* makeUnion(Node* head1, Node* head2) {

    Node* result = nullptr;
    Node* tail = nullptr;

    while (head1) {
        if (!isPresent(result, head1->data)) {
            Node* newNode = new Node(head1->data);
            if (!result) result = tail = newNode;
            else {
                tail->next = newNode;
                tail = newNode;
            }
        }
        head1 = head1->next;
    }

    while (head2) {
        if (!isPresent(result, head2->data)) {
            Node* newNode = new Node(head2->data);
            if (!result) result = tail = newNode;
            else {
                tail->next = newNode;
                tail = newNode;
            }
        }
        head2 = head2->next;
    }

    return result;
}

// Print Linked List
void printList(Node* head) {
    while (head) {
        cout << head->data;
        if (head->next) cout << " -> ";
        head = head->next;
    }
    cout << endl;
}

// Driver Code
int main() {

    // -------- List 1: 9 -> 6 -> 4 -> 3 -> 8 --------
    Node* head1 = new Node(9);
    head1->next = new Node(6);
    head1->next->next = new Node(4);
    head1->next->next->next = new Node(3);
    head1->next->next->next->next = new Node(8);

    // -------- List 2: 1 -> 2 -> 8 -> 6 -> 2 --------
    Node* head2 = new Node(1);
    head2->next = new Node(2);
    head2->next->next = new Node(8);
    head2->next->next->next = new Node(6);
    head2->next->next->next->next = new Node(2);

    Node* unionList = makeUnion(head1, head2);

    cout << "Union: ";
    printList(unionList);

    return 0;
}


